using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. Counts source enumerations:
// each foreach pass over Src() bumps Hits exactly once.
public sealed class CountingProbe
{
    public int Hits;
    public System.Collections.Generic.IEnumerable<int> Src(params int[] xs)
    {
        Hits++;
        foreach (var x in xs) yield return x;
    }
}

